window.AUTH=window.AUTH||{};window.AUTH["23-825"]={"d":"23-825","id":"2024/23-825","n":"Delligatti v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Salvatore Delligatti","date":"2024-08-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/321972/20240808124108689_Delligatti%20-%20Merits%20Brief%20-%20RTF.pdf","side":"pet","n":32},{"k":"respondent","label":"Brief of respondent United States","date":"2024-09-30","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/327160/20240930152003979_23-825bsUnitedStates.pdf","side":"res","n":74},{"k":"reply","label":"Reply of petitioner Salvatore Delligatti","date":"2024-10-30","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/330653/20241030123857350_23-825%20--%20Delligatti%20-%20Reply%20Brief%20rtf.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r19_i42j.pdf","tr":true,"items":[{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"by":{"0":"12, 14, 15, 24, 30, 31","1":"19, 38, 39","2":"2, 3, 4, 8"},"q":[{"src":"brief","b":0,"text":"The word ‘use’ in the statute must be given its ordinary or natural meaning,","cite":"516 U.S. 137, 145"},{"src":"brief","b":0,"text":"a person ‘uses’ an object when he avails himself of it or employs it to facilitate a goal he has in mind.","cite":"516 U.S. 137"},{"src":"brief","b":2,"text":"These various definitions of ‘use’ imply action and implementation.","cite":"516 U.S. at 145"},{"src":"brief","b":2,"text":"force is always an ‘operative factor’ in a crime in which the victim is injured or killed.","cite":"516 U.S. at 413"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"[t]hese various defnitions of `use' imply action.","cite":"516 U. S. 137, 145"}]},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"by":{"0":"26, 27","1":"42, 43","2":"14"},"q":[{"src":"brief","b":0,"text":"the kind of person who might deliberately point the gun and pull the trigger,","cite":"553 U.S. 137, 146"},{"src":"brief","b":0,"text":"violent, aggressive, and purposeful ‘armed career criminal’ behavior.","cite":"553 U.S. at 147"},{"src":"brief","b":1,"text":"the kind of person who might deliberately point the gun and pull the trigger,","cite":"553 U.S. 137, 146"},{"src":"brief","b":1,"text":"violent, aggressive, and purposeful ‘armed career criminal’ behavior.","cite":"553 U.S. at 148"},{"src":"brief","b":2,"text":"attempts to describe recidivists who are ‘the kind of person who might deliberately point the gun and pull the trigger.’","cite":"553 U.S. 137, 146"},{"src":"brief","b":2,"text":"petitioner is wrong to suggest that such offenses necessarily do not involve ‘violent, aggressive, and purposeful armed career criminal behavior.’","cite":"553 U.S. at 148"}]},{"t":"case","label":"Borden v. United States","cite":"593 U.S. 420","y":2021,"id":"2020/19-5410","sc":1,"by":{"0":"8, 12, 22-23, 29, 33-35, 39, 41-42","1":"6, 10, 19, 20, 32, 35, 37, 38, 46","2":"4, 7, 11, 12, 14, 16, 18, 20"},"q":[{"src":"brief","b":0,"text":"‘use of physical force’ means ‘volitional’ or ‘active’ employment of force,","cite":"593 U.S. at 430"},{"src":"brief","b":0,"text":"The first precondition of any term-of-art reading is that the term be present in the disputed statute.","cite":"593 U.S. at 435"},{"src":"brief","b":1,"text":"‘use, attempted use, or threatened use of physical force against the person or property of another.’","cite":"593 U.S. 420, 424"},{"src":"brief","b":1,"text":"the conscious object (not the mere recipient) of the force.","cite":"593 U.S. 420, 430"},{"src":"brief","b":2,"text":"Better to heed the statutory language proper.","cite":"593 U.S. at 443 n.9"},{"src":"brief","b":2,"text":"context and purpose … diverge from those of [the] elements clause,","cite":"593 U.S. at 442"},{"src":"argument","who":"Mr. Kedem","text":"Two of them are already out because of Borden because they can be committed recklessly. There are two others that can only be committed by an act, and so they're going to stay in regardless at least as we interpret them."},{"src":"argument","who":"Mr. Kedem","text":"So it's -- it's an actus reus interpretation of the word \"use.\" Then that was ported over to an Elements Clause in Leocal and then again in Borden."},{"src":"argument","who":"Mr. Kedem","text":"So I -- I accept that, Your Honor, and would respectfully suggest you essentially take the position you did in Borden, which was to say whatever it is, criticism about the categorical approach, but then to give the Elements Clause its natural meaning."}]},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"by":{"0":"13, 41","2":"10, 15"},"q":[{"src":"brief","b":0,"text":"[t]he role of this Court is to apply the statute as it is written—even if [it] think[s] some other approach might accord with good policy.","cite":"571 U.S. at 218"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"would not have occurred in the absence of— that is, but for—the defendant's conduct.","cite":"571 U. S. 204, 211"}]},{"t":"case","label":"Campos-Chavez v. Garland","cite":"144 S. Ct. 1637","y":2024,"id":"2023/22-674","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"gives the provision a substantive effect that is compatible with the rest of the law.","cite":"144 S. Ct. 1637, 1649"}]},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"by":{"0":"25","1":"43"},"q":[{"src":"brief","b":0,"text":"crime [that] amounts to a form of inaction.","cite":"555 U.S. 122, 128"}]},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"by":{"0":"42"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"0":"14, 25, 29, 42","2":"2, 10"},"q":[{"src":"brief","b":0,"text":"the Government argues for a result that the English language tells us not to expect, we must be very wary of the Government’s position.","cite":"599 U.S. at 124"},{"src":"brief","b":0,"text":"the broadest imaginable definitions of its component words.","cite":"599 U.S. at 120"},{"src":"brief","b":2,"text":"the broadest imaginable definitions of its component words,","cite":"599 U.S. 110, 120"},{"src":"brief","b":2,"text":"result that the English language tells us not to expect.","cite":"599 U.S. at 124"}]},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"0":"17, 19, 20, 22, 23, 33, 34, 38, 39","1":"10, 13, 14, 16, 17, 34, 36","2":"9"},"q":[{"src":"brief","b":0,"text":"specif[y] the degree of ‘physical force’ required","cite":"559 U.S. at 142"},{"src":"brief","b":0,"text":"force consisting in a physical act.","cite":"559 U.S. at 139"},{"src":"brief","b":1,"text":"capable of causing physical pain or injury to another person.","cite":"559 U.S. 133, 138, 140"},{"src":"brief","b":1,"text":"force capable of causing physical pain or injury to another person","cite":"559 U.S. 133, 140"},{"src":"brief","b":2,"text":"define[] ‘physical force’ as ‘force consisting in a physical act, esp. a violent act directed against a robbery victim.’","cite":"559 U.S. 133, 139"}]},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"4, 25, 40, 41","2":"17"},"q":[{"src":"brief","b":2,"text":"how much risk it takes for a crime to qualify.","cite":"576 U.S. 591, 597-98"}]},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"by":{"0":"4, 8, 15, 19, 20, 22, 23","1":"19, 37, 38","2":"3, 12"},"q":[{"src":"brief","b":0,"text":"a category of violent, active crimes,","cite":"543 U.S. 1, 11"},{"src":"brief","b":0,"text":"a person actively employs physical force.","cite":"543 U.S. 1, 9"},{"src":"argument","who":"Mr. Kedem","text":"So it's -- it's an actus reus interpretation of the word \"use.\" Then that was ported over to an Elements Clause in Leocal and then again in Borden."}]},{"t":"case","label":"People v. Best","cite":"609 N.Y.S. 2d 478","y":1994,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.%202d/609/478/","by":{"0":"18"}},{"t":"case","label":"People v. Steinberg","cite":"595 N.E.2d 845","y":1992,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/595/845/","by":{"0":"18","1":"43"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"by":{"0":"12, 15","1":"10, 18, 19","2":"2"},"q":[{"src":"brief","b":0,"text":"‘to convert to one’s service’ or ‘to employ,’","cite":"508 U.S. 223, 229"},{"src":"brief","b":1,"text":"carry[ing] out a purpose or action by means of.","cite":"508 U.S. 223, 229"},{"src":"brief","b":1,"text":"against the person or property of another","cite":"508 U.S. 223"}]},{"t":"case","label":"Stokeling v. United States","cite":"586 U.S. 73","y":2019,"id":"2018/17-5554","sc":1,"by":{"0":"8, 20, 21, 22, 33, 34, 37, 38","1":"32, 34, 35, 46","2":"7, 16, 18"},"q":[{"src":"brief","b":0,"text":"snatching of property from another [does] not suffice","cite":"586 U.S. 73, 86"},{"src":"brief","b":0,"text":"violent force necessary to overcome resistance by a victim.","cite":"586 U.S. at 82"},{"src":"brief","b":1,"text":"in a way that would render [them] inapplicable","cite":"586 U.S. 73, 81"},{"src":"brief","b":2,"text":"[t]his Court has ‘repeatedly declined to construe’ elements clauses ‘in a way that would render them inapplicable’ to crimes in numerous States.","cite":"586 U.S. at 81"},{"src":"argument","who":"Justice Barrett","text":"Well, what do you do with the fact that Stokeling especially seems to measure force not from the front end, like force applied, but from the back end on what does the force -- what -- what is its result?"},{"src":"argument","who":"Mr. Kedem","text":"So, respectfully, I -- I don't think Stokeling takes that position. In fact, the whole discussion in Stokeling was how much force do you need to apply, what's the amount of force, to overcome resistance, which, again, the Court wasn't focused on whether the person was injured or not."},{"src":"argument","who":"Justice Barrett","text":"But, counsel, we also said in Castleman and Stokeling that we look at the nature of the crime and that influences the scope of the interpretation."}]},{"t":"case","label":"(iii) Cases—Continued Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"26, 27","2":"16"},"q":[{"src":"brief","b":0,"text":"those who commit a large number of fairly serious crimes as their means of livelihood,","cite":"495 U.S. 575, 587"}]},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"0":"10, 12, 13, 20, 30, 31, 35-39","1":"9-13, 15-17, 19, 21, 32-36, 47","2":"1, 4, 6, 9, 10, 11"},"q":[{"src":"brief","b":0,"text":"the act of employing [it] knowingly as a device to cause physical harm.","cite":"572 U.S. 157, 171"},{"src":"brief","b":0,"text":"indirectly, rather than directly (as with a kick or punch).","cite":"572 U.S. at 171"},{"src":"brief","b":1,"text":"one can cause bodily injury without the use of physical force.","cite":"572 U.S. 157, 170"},{"src":"brief","b":1,"text":"the act of employing poison knowingly as a device to cause physical harm.","cite":"572 U.S. at 171"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"the knowing or intentional causation of bodily injury necessarily involves the use of physical force.","cite":"572 U. S. 157, 169"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"additional reason to read the statute as we do.","cite":"572 U. S., at 167"},{"src":"argument","who":"Mr. Kedem","text":"You look also, for instance, at -- at Castleman. So Castleman gives the example of a squeeze of an arm that causes a bruise, which the Court said would count as common law force for purposes of domestic violence but would not count as violent force for generic purposes, which shows that even the direct application of enough force that sometimes causes an injury, a bruise, is not enough because it's still not a high enough degree of force."},{"src":"argument","who":"Mr. Kedem","text":"So, respectfully, Your Honor, I agree poison is sort of the outer limit, but I do think the Court was making a point there, which is that in response to the defendant's argument in Castleman that essentially you had to apply the force directly in order for it to count, the Court said no, if you put -- put poison in tea, it's very much like pulling the trigger of a gun."},{"src":"argument","who":"Justice Barrett","text":"But, counsel, we also said in Castleman and Stokeling that we look at the nature of the crime and that influences the scope of the interpretation."}]},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"4, 5, 6, 25, 41, 42","1":"6, 30"},"q":[{"src":"brief","b":0,"text":"ambiguities about the breadth of a criminal statute should be resolved in the defendant’s favor,","cite":"588 U.S. at 464"}]},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"apply the rule of lenity and resolve the ambiguity in [Mr. Delligatti’s] favor.","cite":"511 U.S. 39, 54"}]},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"canon of strict construction of criminal statutes,","cite":"520 U.S. 259, 266"}]},{"t":"case","label":"United States v. Laurent","cite":"33 F.4th 63","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/33/63/","by":{"0":"6"}},{"t":"case","label":"United States v. Ramirez","cite":"606 F.3d 396","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/396/","by":{"0":"41"}},{"t":"case","label":"United States v. Scott","cite":"990 F.3d 94","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/990/94/","by":{"0":"6, 18, 42, 43","1":"9, 20, 21, 28, 47"},"q":[{"src":"brief","b":0,"text":"statutes imposing harsh mandatory sentences present a particularly compelling need for invocation of the rule of lenity.","cite":"990 F.3d at 137"},{"src":"brief","b":1,"text":"whether a defendant acts by commission or omission, in every instance, it is his intentional use of physical force against the person of another that causes death.","cite":"990 F.3d at 123"},{"src":"brief","b":1,"text":"causes death by breaching a legal duty to check or redress violent force because he intends thereby for that force to cause serious physical injury","cite":"990 F.3d 94, 101"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"fortyseven non-specialist instances of `use of physical force.'","cite":"990 F. 3d 94, 129, n. 8"}]},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"by":{"0":"5, 8, 16, 17, 41","1":"6, 8, 39","2":"8, 13, 18"},"q":[{"src":"brief","b":0,"text":"specific actions against specific persons or their property,","cite":"596 U.S. 845, 856"},{"src":"brief","b":0,"text":"specific actions against specific persons or their property.","cite":"596 U.S. 845, 856"},{"src":"brief","b":2,"text":"[p]lainly this language requires the government to prove that the defendant took specific actions against specific persons or their property.","cite":"596 U.S. 845, 856"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"pose[d] an abstract risk to community peace and order.","cite":"596 U. S., at 856"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"does not require—in fact, it precludes—an inquiry into how any particular defendant may commit the crime.","cite":"596 U. S. 845, 850"}]},{"t":"case","label":"United States v. Walker","cite":"442 F.3d 787","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/442/787/","by":{"0":"40"}},{"t":"case","label":"United States v. Williams","cite":"343 F.3d 432","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/343/432/","by":{"0":"41"}},{"t":"case","label":"Voisine v. United States","cite":"579 U.S. 686","y":2016,"id":"2015/14-10154","sc":1,"by":{"0":"12, 15, 16","1":"19, 32, 37","2":"4"},"q":[{"src":"argument","who":"Mr. Feigin","text":"It's the same thing the Court said in Voisine. They're at risk because we're not quite sure how the divisibility analysis is going to shake out."},{"src":"argument","who":"Mr. Feigin","text":"The point I'm making is I -- I think there's -- I think that approaching this with some sort of degree of common sense that is here informed by two millennia of common law, and Voisine looked at the common law to a certain extent in interpreting what the term \"use\" meant."},{"src":"argument","who":"Mr. Feigin","text":"And if you look at the appendix we submitted in Voisine, most of the assault statutes the Court was worried about there are defined in terms of causation of harm or causation of offense of touching."}]},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"25, 26, 27"},"q":[{"src":"brief","b":0,"text":"are especially likely to inflict grave harm when in possession of a firearm.","cite":"595 U.S. 360, 375"},{"src":"brief","b":0,"text":"‘career criminals,’ ‘repeat offenders,’ ‘habitual offenders,’ ‘recidivists,’ ‘revolving door’ offenders, and ‘three time losers,’","cite":"595 U.S. at 372"}]},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)"],"by":{"0":"15, 19"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1213","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"28,29"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"0":"14"}},{"t":"case","label":"Allen v. United States","cite":"2023 WL 4145321","y":2023,"court":"6th Cir. June 23","by":{"1":"42"}},{"t":"case","label":"Association for Molecular Pathology v. Myriad Genetics, Inc.","cite":"569 U.S. 576","y":2013,"id":"2012/12-398","sc":1,"by":{"1":"22","2":"5"}},{"t":"case","label":"Astor v. Merritt","cite":"111 U.S. 202","y":1884,"id":"scdb/1883-211","sc":1,"by":{"1":"19"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"by":{"1":"47"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"perils of relying on the fate of prior bills to divine the meaning of enacted legislation.","cite":"566 U.S. 399, 422"}]},{"t":"case","label":"Commonwealth v. Hall","cite":"78 N.E.2d 644","y":1948,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/78/644/","by":{"1":"28"}},{"t":"case","label":"Davis v. Commonwealth","cite":"335 S.E.2d 375","y":1985,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/335/375/","by":{"1":"28","2":"20"}},{"t":"case","label":"Faunteroy v. United States","cite":"413 A.2d 1294","y":1980,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/413/1294/","by":{"1":"28","2":"20"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"by":{"1":"28"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"by":{"1":"46"}},{"t":"case","label":"Mathis v. United States","cite":"579 U.S. 500","y":2016,"id":"2015/15-6092","sc":1,"by":{"1":"6"},"q":[{"src":"brief","b":1,"text":"the particular facts of the case.","cite":"579 U.S. 500, 504"}]},{"t":"case","label":"Miles v. Apex Marine Corp.","cite":"498 U.S. 19","y":1990,"id":"1990/89-1158","sc":1,"by":{"1":"28"}},{"t":"case","label":"People v. Beardsley","cite":"113 N.W. 1128","y":1907,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./113/1128/","by":{"1":"25"}},{"t":"case","label":"People v. Best","cite":"609 N.Y.S.2d 478","y":1994,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/609/478/","by":{"1":"43"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"by":{"1":"29"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"by":{"1":"29"}},{"t":"case","label":"Shular v. United States","cite":"589 U.S. 154","y":2020,"id":"2019/18-6662","sc":1,"by":{"1":"47"}},{"t":"case","label":"State v. Barnes","cite":"212 S.W. 100","y":1919,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./212/100/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Evangelista","cite":"353 S.E.2d 375","y":1987,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/353/375/","by":{"1":"28"}},{"t":"case","label":"State v. Miranda","cite":"878 A.2d 1118","y":2005,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/878/1118/","by":{"1":"28","2":"19"}},{"t":"case","label":"State v. Smith","cite":"65 Me. 257","y":1876,"url":"https://www.courtlistener.com/c/Me./65/257/","by":{"1":"25, 28","2":"20"}},{"t":"case","label":"State v. Spates","cite":"405 A.2d 656","y":1978,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/405/656/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Staples","cite":"148 N.W. 283","y":1914,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./148/283/","by":{"1":"28"}},{"t":"case","label":"State v. Valley","cite":"571 A.2d 579","y":1989,"court":"Vt.","url":"https://www.courtlistener.com/c/A.2d/571/579/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Williquette","cite":"385 N.W.2d 145","y":1986,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/385/145/","by":{"1":"28","2":"20"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"by":{"1":"46"}},{"t":"case","label":"Territory v. Manton","cite":"19 P. 387","y":1888,"court":"Mont.","url":"https://www.courtlistener.com/c/P./19/387/","by":{"1":"24, 25","2":"7"},"q":[{"src":"argument","who":"Mr. Feigin","text":"And the common law sources that we cite, both Hall and Territory against Manton, which is an 1888 case, have no trouble describing those kinds of omission cases as involving the use of force."}]},{"t":"case","label":"United States v. Báez-Martínez","cite":"950 F.3d 119","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/950/119/","by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"after all, * * * simply physical force distinguished by the degree of harm sought to be caused.","cite":"950 F.3d 119, 132"}]},{"t":"case","label":"United States v. Bowers","cite":"2022 WL 17718686","y":2022,"court":"W.D. Pa. Dec. 15","by":{"1":"41, 42"},"q":[{"src":"brief","b":1,"text":"cannot be a crime of violence.","cite":"2022 WL 17718686"}]},{"t":"case","label":"United States v. Christie","cite":"717 F.3d 1156","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/717/1156/","by":{"1":"31"}},{"t":"case","label":"United States v. Keene","cite":"955 F.3d 391","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/955/391/","by":{"1":"7"}},{"t":"case","label":"United States v. Mayo","cite":"90 F.3d 218","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/90/218/","by":{"1":"41"}},{"t":"case","label":"United States v. Ortiz-Orellana","cite":"901 F.4th 689","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/901/689/","by":{"1":"42"}},{"t":"case","label":"United States v. Rodriguez-Moreno","cite":"526 U.S. 275","y":1999,"id":"1998/97-1139","sc":1,"by":{"1":"6"}},{"t":"case","label":"Zessman v. State","cite":"573 P.2d 1174","y":1978,"court":"Nev.","url":"https://www.courtlistener.com/c/P.2d/573/1174/","by":{"1":"28"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(2)(B)","(e)(2)(B)(i)","(c)(1)(1994)","(c)(1)(A)","(c)(1)(A)(i)","(c)(3)(A)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"1":"29, 5, 5, 38, 42, 42, 42, 42, 42"},"q":[{"src":"brief","b":1,"text":"has as an element the use, attempted use, or threatened use of physical force against the person or property of an- other.","cite":"18 U.S.C. 924(c)(3)(A)"},{"src":"brief","b":1,"text":"by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense.","cite":"18 U.S.C. 924(c)(3)(B)"}]},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(F)"],"by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 249","url":"https://www.law.cornell.edu/uscode/text/18/249","subs":["(a)(1)","(a)(1)(B)"],"stext":{"head":"§249. Hate crime acts","paras":[[0,"(a) In General.—"],[1,"(1) Offenses involving actual or perceived race, color, religion, or national origin.—Whoever, whether or not acting under color of law, willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived race, color, religion, or national origin of any person—"],[2,"(A) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[2,"(B) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[3,"(i) death results from the offense; or"],[3,"(ii) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[1,"(2) Offenses involving actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability.—"],[2,"(A) In general.—Whoever, whether or not acting under color of law, in any circumstance described in subparagraph (B) or paragraph (3), willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability of any person—"],[3,"(i) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[3,"(ii) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[4,"(I) death results from the offense; or"],[4,"(II) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[2,"(B) Circumstances described.—For purposes of subparagraph (A), the circumstances described in this subparagraph are that—"],[3,"(i) the conduct described in subparagraph (A) occurs during the course of, or as the result of, the travel of the defendant or the victim—"],[4,"(I) across a State line or national border; or"],[4,"(II) using a channel, facility, or instrumentality of interstate or foreign commerce;"],[3,"(ii) the defendant uses a channel, facility, or instrumentality of interstate or foreign commerce in connection with the conduct described in subparagraph (A);"],[3,"(iii) in connection with the conduct described in subparagraph (A), the defendant employs a firearm, dangerous weapon, explosive or incendiary device, or other weapon that has traveled in interstate or foreign commerce; or"],[3,"(iv) the conduct described in subparagraph (A)—"],[4,"(I) interferes with commercial or other economic activity in which the victim is engaged at the time of the conduct; or"],[4,"(II) otherwise affects interstate or foreign commerce."],[1,"(3) Offenses occurring in the special maritime or territorial jurisdiction of the united states.—Whoever, within the special maritime or territorial jurisdiction of the United States, engages in conduct described in paragraph (1) or in paragraph (2)(A) (without regard to whether that conduct occurred in a circumstance described in paragraph (2)(B)) shall be subject to the same penalties as prescribed in those paragraphs."],[1,"(4) Guidelines.—All prosecutions conducted by the United States under this section shall be undertaken pursuant to guidelines issued by the Attorney General, or the designee of the Attorney General, to be included in the United States Attorneys' Manual that shall establish neutral and objective criteria for determining whether a crime was committed because of the actual or perceived status of any person."],[1,"(5) Lynching.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[1,"(6) Other conspiracies.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, or if the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[0,"(b) Certification Requirement.—"],[1,"(1) In general.—No prosecution of any offense described in this subsection may be undertaken by the United States, except under the certification in writing of the Attorney General, or a designee, that—"],[2,"(A) the State does not have jurisdiction;"],[2,"(B) the State has requested that the Federal Government assume jurisdiction;"],[2,"(C) the verdict or sentence obtained pursuant to State charges left demonstratively unvindicated the Federal interest in eradicating bias-motivated violence; or"],[2,"(D) a prosecution by the United States is in the public interest and necessary to secure substantial justice."],[1,"(2) Rule of construction.—Nothing in this subsection shall be construed to limit the authority of Federal officers, or a Federal grand jury, to investigate possible violations of this section."],[0,"(c) Definitions.—In this section—"],[1,"(1) the term \"bodily injury\" has the meaning given such term in section 1365(h)(4) of this title, but does not include solely emotional or psychological harm to the victim;"],[1,"(2) the term \"explosive or incendiary device\" has the meaning given such term in section 232 of this title;"],[1,"(3) the term \"firearm\" has the meaning given such term in section 921(a) of this title;"],[1,"(4) the term \"gender identity\" means actual or perceived gender-related characteristics; and"],[1,"(5) the term \"State\" includes the District of Columbia, Puerto Rico, and any other territory or possession of the United States."],[0,"(d) Statute of Limitations.—"],[1,"(1) Offenses not resulting in death.—Except as provided in paragraph (2), no person shall be prosecuted, tried, or punished for any offense under this section unless the indictment for such offense is found, or the information for such offense is instituted, not later than 7 years after the date on which the offense was committed."],[1,"(2) Death resulting offenses.—An indictment or information alleging that an offense under this section resulted in death may be found or instituted at any time without limitation."],[0,"(e) Supervised Release.—If a court includes, as a part of a sentence of imprisonment imposed for a violation of subsection (a), a requirement that the defendant be placed on a term of supervised release after imprisonment under section 3583, the court may order, as an explicit condition of supervised release, that the defendant undertake educational classes or community service directly related to the community harmed by the defendant's offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/249?type=usc&year=mostrecent&link-type=html"},"by":{"1":"41","2":"21"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(33)(A)(2012)","(a)(33)(A)(ii)(2012)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"by":{"1":"32, 15"},"q":[{"src":"brief","b":1,"text":"has, as an element, the use or attempted use of physical force.","cite":"18 U.S.C. 921(a)(33)(A)(ii)"},{"src":"argument","who":"Mr. Feigin","text":"That's in Section 921.33(a). The definition of \"misdemeanor, crime of domestic violence,\" doesn't even have a Residual Clause. And if you look at the appendix we submitted in Voisine, most of the assault statutes the Court was worried about there are defined in terms of causation of harm or causation of offense of touching."}]},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(2012)","(g)(9)(2012)","(g)(9)"],"by":{"1":"32, 32, 5-8, 12, 13, 18, 27-30, 33, 40-42, 44-47"}},{"t":"usc","label":"18 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/18/1111","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/18/1112","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1513","url":"https://www.law.cornell.edu/uscode/text/18/1513","subs":["(b)"],"by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1955","url":"https://www.law.cornell.edu/uscode/text/18/1955","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1958","url":"https://www.law.cornell.edu/uscode/text/18/1958","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1959","url":"https://www.law.cornell.edu/uscode/text/18/1959","subs":["(a)(5)"],"stext":{"head":"§1959. Violent crimes in aid of racketeering activity","paras":[[0,"(a) Whoever, as consideration for the receipt of, or as consideration for a promise or agreement to pay, anything of pecuniary value from an enterprise engaged in racketeering activity, or for the purpose of gaining entrance to or maintaining or increasing position in an enterprise engaged in racketeering activity, murders, kidnaps, maims, assaults with a dangerous weapon, commits assault resulting in serious bodily injury upon, or threatens to commit a crime of violence against any individual in violation of the laws of any State or the United States, or attempts or conspires so to do, shall be punished—"],[1,"(1) for murder, by death or life imprisonment, or a fine under this title, or both; and for kidnapping, by imprisonment for any term of years or for life, or a fine under this title, or both;"],[1,"(2) for maiming, by imprisonment for not more than thirty years or a fine under this title, or both;"],[1,"(3) for assault with a dangerous weapon or assault resulting in serious bodily injury, by imprisonment for not more than twenty years or a fine under this title, or both;"],[1,"(4) for threatening to commit a crime of violence, by imprisonment for not more than five years or a fine under this title, or both;"],[1,"(5) for attempting or conspiring to commit murder or kidnapping, by imprisonment for not more than ten years or a fine under this title, or both; and"],[1,"(6) for attempting or conspiring to commit a crime involving maiming, assault with a dangerous weapon, or assault resulting in serious bodily injury, by imprisonment for not more than three years or a fine of 1 under this title, or both."],[0,"(b) As used in this section—"],[1,"(1) \"racketeering activity\" has the meaning set forth in section 1961 of this title; and"],[1,"(2) \"enterprise\" includes any partnership, corporation, association, or other legal entity, and any union or group of individuals associated in fact although not a legal entity, which is engaged in, or the activities of which affect, interstate or foreign commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1959?type=usc&year=mostrecent&link-type=html"},"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"for the purpose of * * * maintaining or increasing position in an enterprise engaged in racketeering activity.","cite":"18 U.S.C. 1959(a)(5)"}]},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(g)"],"by":{"1":"27"}},{"t":"case","label":"Avellaneda v. State","cite":"496 S.W.3d 311","y":2016,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/496/311/","by":{"2":"19"}},{"t":"case","label":"Bradley v. United States","cite":"856 A.2d 1157","y":2004,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/856/1157/","by":{"2":"19"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"581 U.S. 385","y":2017,"id":"2016/16-54","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"jurisdictional surveys … can sometimes be useful when interpreting a federal provision that has a well-established meaning under state law,","cite":"581 U.S. 385"}]},{"t":"case","label":"State v. Small","cite":"100 So.3d 797","y":2012,"court":"La.","url":"https://www.courtlistener.com/c/So.3d/100/797/","by":{"2":"19"}},{"t":"case","label":"State v. Sudberry","cite":"2012 WL 5544611","y":2012,"court":"Tenn. Crim. App. Nov. 14","by":{"2":"20"}},{"t":"case","label":"United States v. Harris","cite":"88 F.4th 458","y":2023,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/88/458/","by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"‘all pickpockets are criminals’ does not validly imply that ‘all criminals are pickpockets.’","cite":"88 F.4th 458, 465"}]},{"t":"law","label":"Pub. L. No. 111-84","url":"https://www.govinfo.gov/link/plaw/111/public/84","by":{"2":"21"}}]};